// from src/locales/de/blog.ts. Body + FAQs for article '200kb-image-job-portal-settings' (de).
// This file is the single source for this article's de body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Jobportale und Bewerbungsformulare sind wählerisch bei Bildern. Sie setzen Dateigrößenobergrenzen, Abmessungsregeln und Formatlisten und lehnen dann alles ab, was sie bricht.</p>\n<p>Zweihundert Kilobyte sind die häufigste Obergrenze für Fotos und Dokumente auf diesen Systemen. Sie ist großzügig genug für ein scharfes Bild und streng genug, um ihre Server schnell zu halten.</p>\n<p>Dieser Artikel erklärt, wie Sie 200-KB-Bilder vorbereiten, die Jobportale und Formulare beim ersten Versuch bestehen.</p>\n<h2 id=\"why-portals-use-200kb\">Warum Jobportale Bilder auf 200 KB begrenzen</h2>\n<p>Ein Jobportal speichert Millionen von Bewerbungen. Wenn jedes Foto 5 MB groß wäre, wären die Speicher- und Bandbreitenkosten enorm.</p>\n<p>Eine 200-KB-Grenze hält das System schnell. Personalverantwortliche können Dutzende von Profilen hintereinander öffnen, ohne auf schwere Bilder zu warten.</p>\n<p>Die Grenze sorgt außerdem für Fairness. Jeder Bewerber bekommt dasselbe Budget, also verschafft sich niemand durch eine schwerere Datei einen Vorteil.</p>\n<p>Und schließlich reichen 200 KB für die Aufgabe. Ein Personalverantwortlicher braucht ein klares Gesicht und ein lesbares Dokument, kein Foto in Druckqualität.</p>\n<p>Den Grund zu verstehen, hilft Ihnen, die Grenze zu akzeptieren. Sie ist nicht da, um Sie zu ärgern – sie ist da, um das System für alle am Laufen zu halten.</p>\n<h2 id=\"profile-photo-rules\">Profilfotoregeln auf Jobportalen</h2>\n<p>Die meisten Portale wollen ein aktuelles Porträt vor schlichtem Hintergrund. Das Gesicht sollte frontal, gut beleuchtet und im Rahmen zentriert sein.</p>\n<p>Abmessungen werden oft zusammen mit der Dateigröße angegeben. Ein übliches Paar ist maximal 200 KB mit einer empfohlenen Größe von 600 mal 600 Pixeln oder ähnlich.</p>\n<p>Formate sind meist auf JPG und PNG beschränkt. WebP wird selten aufgeführt, verwenden Sie also JPG für Portalfotos, es sei denn, die Regeln sagen etwas anderes.</p>\n<p>Prüfen Sie, ob das Portal Ihr Foto zu einem Kreis zuschneidet. Wenn ja, halten Sie das Gesicht zentriert mit Platz darum, sonst werden die Ränder abgeschnitten.</p>\n<p>Sehen Sie sich das Foto nach dem Hochladen in der Vorschau an. Die meisten Portale zeigen, wie es für Personalverantwortliche aussehen wird – und diese Vorschau ist Ihre letzte Chance, ein Problem zu beheben.</p>\n<h2 id=\"resume-documents\">Lebensläufe, Zeugnisse und Dokumentenscans</h2>\n<p>Dokumente stehen vor derselben 200-KB-Grenze wie Fotos, verhalten sich aber anders. Ein eingescanntes Zeugnis besteht größtenteils aus Weißraum und komprimiert sich deshalb leicht.</p>\n<p>Scannen Sie mit 300 DPI für das beste Gleichgewicht. Höhere Auflösungen erzeugen riesige Dateien, während niedrigere Auflösungen den Text verwischen.</p>\n<p>Sehen Sie sich nach dem Komprimieren den kleinsten Text in der Vorschau an. Registrierungsnummern, Daten und Unterschriften leiden als Erste.</p>\n<p>Wenn ein Dokument ein eingebettetes Foto enthält, bestimmt das Foto die Schwierigkeit. Ein Zeugnis mit Porträt braucht mehr Sorgfalt als eine schlichte Textseite.</p>\n<p>Behalten Sie von jedem Dokument eine hochauflösende Kopie. Portale verlangen später vielleicht eine größere Version, und eine 200-KB-Datei lässt sich nicht sauber vergrößern.</p>\n<h2 id=\"signature-rules\">Unterschriftsbilder für Formulare</h2>\n<p>Viele Formulare verlangen neben dem Foto eine eingescannte Unterschrift. Unterschriften komprimieren sich wunderbar, weil sie größtenteils aus leerem Raum bestehen.</p>\n<p>Unterschreiben Sie auf weißem Papier mit einem dunklen Stift. Eine kräftige, dunkle Unterschrift übersteht die Komprimierung weit besser als eine schwache Bleistiftlinie.</p>\n<p>Scannen oder fotografieren Sie die Unterschrift gerade von vorn. Eine schiefe Unterschrift verschwendet Pixel auf leere Ecken und kann unprofessionell wirken.</p>\n<p>Schneiden Sie vor dem Komprimieren eng um die Unterschrift herum zu. Das Entfernen der leeren Ränder gibt der Unterschrift mehr vom 200-KB-Budget.</p>\n<p>Prüfen Sie das Ergebnis in voller Größe. Die Unterschrift sollte wie Tinte auf Papier aussehen, nicht wie ein grauer Fleck.</p>\n<h2 id=\"format-choice-portals\">Das Format für Portale wählen</h2>\n<p>JPG ist das sicherste Format für Portal-Uploads. Jedes Jobportal akzeptiert es, und bei 200 KB ist seine Qualität ausgezeichnet.</p>\n<p>PNG wird von den meisten Portalen akzeptiert, ist aber eine schlechte Wahl für Fotos. Ein Foto in PNG braucht vielleicht starke Abmessungsschnitte, um 200 KB zu erreichen.</p>\n<p>WebP wird von Jobportalen selten akzeptiert. Auch wenn es besser aussieht, ist eine abgelehnte Datei nutzlos – riskieren Sie es also nicht, es sei denn, die Regeln listen WebP auf.</p>\n<p>Für Dokumente gewinnt JPG meist ebenfalls. Ein eingescanntes Zeugnis in JPG bei 200 KB bleibt lesbar, während PNG vielleicht kleinere Abmessungen braucht, um zu passen.</p>\n<p>Wenn die Regeln unklar sind, laden Sie JPG hoch. Es ist das Format, um das Portale herum gebaut wurden, und es verursacht nie ein Kompatibilitätsproblem.</p>\n<h2 id=\"step-by-step-portal\">Schritt für Schritt: Ein Portalfoto vorbereiten</h2>\n<p>Machen Sie ein frisches Porträt mit gutem Licht und schlichtem Hintergrund. Ein Foto von heute schlägt ein fünf Jahre altes Foto in jeder Hinsicht.</p>\n<p>Öffnen Sie den <a href=\"/de/bild-auf-200-kb-komprimieren/\">200-KB-Kompressor</a> und laden Sie das Original hoch. Behalten Sie JPG als Ausgabeformat.</p>\n<p>Lassen Sie die automatische Qualitätssuche die beste Qualität finden, die unter 200 KB passt. Sehen Sie sich das Gesicht in voller Größe in der Vorschau an und prüfen Sie Augen und Kanten.</p>\n<p>Laden Sie die Datei herunter und prüfen Sie ihre Größe. Sie sollte knapp unter 200 KB liegen, meist zwischen 198 KB und 199,9 KB.</p>\n<p>Laden Sie sie im Portal hoch und prüfen Sie die Vorschau. Vergewissern Sie sich, dass das Gesicht zentriert ist, das Bild richtig herum ist und nichts abgeschnitten wird.</p>\n<h2 id=\"common-rejections\">Häufige Ablehnungsgründe und Lösungen</h2>\n<p>„Datei zu groß“ ist die häufigste Ablehnung. Die Lösung ist Komprimierung, prüfen Sie aber zuerst die genaue Grenze, denn manche Portale begrenzen auf 100 KB statt 200 KB.</p>\n<p>„Falsches Format“ ist die zweithäufigste. Eine WebP-Datei auf einem Portal, das nur JPG akzeptiert, scheitert sofort – wandeln Sie also vor dem Hochladen in JPG um.</p>\n<p>Auch falsche Abmessungen verursachen Ablehnungen. Wenn das Portal 600 mal 600 Pixel will, scheitert eine 200-KB-Datei mit anderen Abmessungen trotzdem.</p>\n<p>Verschwommene oder dunkle Fotos werden von menschlichen Prüfern abgelehnt. Die Komprimierung kann eine schlechte Quelle nicht reparieren, nehmen Sie das Foto also mit besserem Licht neu auf.</p>\n<p>Lesen Sie jedes Mal die genaue Fehlermeldung. Sie sagt Ihnen, welche Regel gebrochen wurde, und jede Regel hat eine andere Lösung.</p>\n<h2 id=\"multiple-documents\">Mehrere Dokumente auf einmal bearbeiten</h2>\n<p>Eine einzelne Bewerbung braucht vielleicht ein Foto, eine Unterschrift, einen Lebenslauf und zwei Zeugnisse. Sie einzeln zu komprimieren, ist langsam.</p>\n<p>Verwenden Sie den Stapelmodus, um sie alle gemeinsam auf 200 KB zu komprimieren. Jede Datei wird auf dasselbe Ziel verarbeitet und als ZIP heruntergeladen.</p>\n<p>Prüfen Sie jede Datei nach dem Entpacken. Eine Unterschrift und ein Porträt haben unterschiedliche Anforderungen, und eine davon braucht vielleicht einen neuen Versuch mit anderen Einstellungen.</p>\n<p>Benennen Sie die Dateien vor dem Hochladen klar. Ein Name wie resume-200kb.jpg verhindert Verwechslungen zwischen ähnlichen Dokumenten.</p>\n<p>Laden Sie sie einzeln hoch und bestätigen Sie jede. Ein Portal, das das Foto akzeptiert, kann das Zeugnis trotzdem ablehnen, und jedes braucht seine eigene Prüfung.</p>\n<h2 id=\"mobile-applications\">Vom Handy aus bewerben</h2>\n<p>Die meisten Bewerbungen finden heute auf Handys statt. Der Ablauf ist derselbe, mit ein paar handyspezifischen Tipps.</p>\n<p>Wählen Sie das Originalfoto aus Ihrer Galerie, keine Kopie, die aus einer Chat-App gespeichert wurde. Chat-Apps verkleinern Fotos, bevor Sie sie überhaupt sehen.</p>\n<p>iPhone-Fotos können HEIC-Dateien sein. Laden Sie sie direkt ins Tool hoch; es übernimmt die Umwandlung während der Komprimierung.</p>\n<p>Prüfen Sie die Datei nach dem Herunterladen in Ihrer Dateien-App. Vergewissern Sie sich, dass die Größe unter 200 KB liegt, bevor Sie zum Portal zurückwechseln.</p>\n<p>Lassen Sie das Portal in einem anderen Tab offen. Zwischen Tool und Portal zu wechseln, ist leichter, als das Formular von vorn neu auszufüllen.</p>\n<h2 id=\"after-submission\">Nach dem Einreichen: Was man behalten sollte</h2>\n<p>Behalten Sie die komprimierten Dateien, die Sie eingereicht haben. Wenn das Portal Sie bittet, erneut hochzuladen, haben Sie die genauen Dateien bereit.</p>\n<p>Behalten Sie auch die Originale. Eine künftige Bewerbung hat vielleicht andere Regeln, und nur das Original lässt sich frisch komprimieren.</p>\n<p>Speichern Sie eine Kopie der Bestätigungsseite oder E-Mail. Sie beweist, dass die Bewerbung eingereicht wurde, mit Datum und Referenznummer.</p>\n<p>Notieren Sie, welche Einstellungen funktioniert haben. Eine kurze Notiz wie „Portal X akzeptiert JPG mit 200 KB“ spart bei der nächsten Bewerbung Zeit.</p>\n<p>Gute Aufzeichnungen verwandeln einen stressigen Vorgang in Routine. Die nächste Bewerbung dauert Minuten statt Stunden.</p>\n<h2 id=\"beyond-200kb\">Wenn das Portal eine andere Größe will</h2>\n<p>Manche Portale begrenzen stattdessen auf 50 KB oder 100 KB. Verwenden Sie in diesen Fällen den <a href=\"/de/bild-auf-50-kb-komprimieren/\">50-KB-Kompressor</a> oder den <a href=\"/de/bild-auf-100-kb-komprimieren/\">100-KB-Kompressor</a>, wie erforderlich.</p>\n<p>Andere erlauben 500 KB oder mehr. Wenn die Grenze großzügig ist, verwenden Sie den <a href=\"/de/bild-auf-500-kb-komprimieren/\">500-KB-Kompressor</a> für die beste Qualität.</p>\n<p>Angepasste Grenzen verlangen den <a href=\"/de/bild-auf-zieldateigroesse-komprimieren/\">Zielgrößen-Kompressor</a>. Tippen Sie die genaue Zahl ein, die das Portal verlangt, und lassen Sie ihn nach der besten Qualität suchen.</p>\n<p>Das Prinzip ändert sich nie: Verwenden Sie die größte Größe, die das Portal erlaubt. Qualität ist die zusätzlichen Kilobyte wert, wenn sie verfügbar sind.</p>\n<h2 id=\"photo-day\">Vorbereitung am Fototag</h2>\n<p>Das beste Portalfoto beginnt, bevor die Kamera herauskommt. Wählen Sie eine schlichte, hellfarbige Wand und stellen Sie sich einen Schritt davon entfernt, um harte Schatten zu vermeiden.</p>\n<p>Stellen Sie sich vor ein Fenster oder eine helle Lampe. Licht von vorn füllt das Gesicht gleichmäßig, während Licht von hinten das Gesicht zur Silhouette macht.</p>\n<p>Tragen Sie ein einfarbiges Oberteil in mittlerem Ton. Unruhige Muster lenken das Auge ab und kosten Kilobyte, während eine einfarbige Farbe den Fokus aufs Gesicht hält.</p>\n<p>Machen Sie mehrere Aufnahmen und wählen Sie die schärfste. Ein winziger Unterschied in der Schärfe zählt bei 200 KB mehr, als die meisten erwarten.</p>\n<p>Prüfen Sie das Foto vor dem Komprimieren auf einem größeren Bildschirm. Ein Gesicht, das auf einem Handybildschirm gut aussieht, kann auf einem Laptop Probleme zeigen.</p>\n<h2 id=\"document-checklist\">Eine Dokumenten-Checkliste für Bewerbungen</h2>\n<p>Listen Sie jedes Dokument auf, das die Bewerbung braucht, bevor Sie beginnen. Ein Foto, eine Unterschrift, ein Lebenslauf und Zeugnisse sind die übliche Zusammenstellung.</p>\n<p>Prüfen Sie die Regeln für jedes einzeln. Das Foto kann auf 200 KB begrenzt sein, während ein Zeugnis auf 100 KB begrenzt ist – und eine Verwechslung verursacht Ablehnungen.</p>\n<p>Scannen Sie Dokumente mit 300 DPI auf einem sauberen Scannerbett. Staub und Schatten fügen Rauschen hinzu, das Kilobyte für nichts verschwendet.</p>\n<p>Komprimieren Sie jedes Dokument auf seine eigene Grenze. Der Stapelmodus verarbeitet unterschiedliche Dateien, aber jede Datei braucht danach trotzdem ihre eigene Prüfung.</p>\n<p>Haken Sie jedes Dokument ab, sobald Sie es hochladen. Eine Checkliste verwandelt eine stressige Bewerbung in einen ruhigen Schritt-für-Schritt-Vorgang.</p>\n<h2 id=\"deadline-pressure\">Unter Termindruck arbeiten</h2>\n<p>Bewerbungen kommen oft mit engen Fristen. Die schlechteste Zeit, Komprimierung zu lernen, ist die Nacht, bevor das Formular schließt.</p>\n<p>Bereiten Sie Ihr Foto und Ihre Dokumente früh vor. Komprimieren Sie sie Tage im Voraus und speichern Sie sie in einem Ordner mit dem Namen der Bewerbung.</p>\n<p>Testen Sie den Upload einen Tag vor der Frist. Wenn das Portal eine Datei ablehnt, haben Sie noch Zeit, sie zu korrigieren.</p>\n<p>Halten Sie das Tool als Lesezeichen und die Originale griffbereit. Ein vorbereiteter Bewerber ist in Minuten fertig, während andere in Panik geraten.</p>\n<p>Wenn das Portal nahe der Frist ausfällt, bleiben Sie ruhig und versuchen Sie es erneut. Systeme erholen sich oft, und ein vorbereiteter Dateisatz bedeutet, dass Sie nur ein funktionierendes Zeitfenster brauchen.</p>\n<h2 id=\"reusing-photos\">Ein Portalfoto für mehrere Bewerbungen wiederverwenden</h2>\n<p>Ein gutes Portalfoto kann viele Bewerbungen bedienen. Sobald Sie ein sauberes 200-KB-Porträt haben, verwenden Sie es überall, wo die Regeln es erlauben.</p>\n<p>Prüfen Sie jedes Mal die Regeln. Ein Portal will vielleicht 200 KB, während ein anderes 100 KB will – und dieselbe Datei kann nicht beiden dienen.</p>\n<p>Aktualisieren Sie das Foto alle ein oder zwei Jahre. Ein Foto, das Ihnen nicht mehr ähnlich sieht, kann bei der Überprüfung Probleme verursachen.</p>\n<p>Speichern Sie das komprimierte Foto bei der Bewerbung, zu der es gehört. Ein Foto, das im Downloads-Ordner liegt, ist ein Foto, das darauf wartet, verloren zu gehen.</p>\n<p>Wenn sich die Regeln ändern, komprimieren Sie frisch vom Original. Komprimieren Sie die alte 200-KB-Kopie nie erneut, denn jede Runde fügt Schaden hinzu.</p>\n<h2 id=\"verification-steps\">Überprüfungsschritte im Portal</h2>\n<p>Viele Portale prüfen das Foto anhand eines Ausweisdokuments. Das Foto muss dieselbe Person klar zeigen, ohne starke Filter oder Bearbeitungen.</p>\n<p>Vermeiden Sie Beauty-Filter vor dem Komprimieren. Geglättete Haut und veränderte Merkmale können die Überprüfung scheitern lassen und die Bewerbung verzögern.</p>\n<p>Halten Sie den Hintergrund schlicht und die Beleuchtung gleichmäßig. Überprüfungssysteme lesen Gesichter besser, wenn nichts von ihnen ablenkt.</p>\n<p>Wenn die Überprüfung scheitert, nehmen Sie das Foto neu auf, statt das alte zu bearbeiten. Ein frisches, ehrliches Foto besteht zuverlässiger als ein repariertes.</p>\n<p>Denken Sie daran, dass Komprimierung die Identität nicht verändert. Ein klares 200-KB-Foto verifiziert sich genauso gut wie das Original, solange das Gesicht scharf bleibt.</p>\n<h2 id=\"long-term-habits\">Langfristige Gewohnheiten für Bewerbungsfotos</h2>\n<p>Halten Sie ein einsatzbereites Portalfoto auf Ihrem Gerät. Ein sauberes Porträt, bereits auf 200 KB komprimiert, verwandelt eine neue Bewerbung in eine Fünf-Minuten-Aufgabe.</p>\n<p>Erneuern Sie das Foto, wenn sich Ihr Aussehen ändert. Ein Foto von vor drei Jahren kann bei der Überprüfung Verwirrung stiften, auch wenn es technisch gültig ist.</p>\n<p>Speichern Sie das Original neben der komprimierten Kopie. Das Original ist der Master, und jede komprimierte Version sollte von ihm stammen.</p>\n<p>Notieren Sie die Regeln von Portalen, die Sie oft nutzen. Eine kurze Liste mit Grenzen und Formaten erspart Ihnen, jedes Mal das Kleingedruckte zu lesen.</p>\n<p>Gute Gewohnheiten summieren sich. Jede Bewerbung wird leichter, und der Stress der Fristen verblasst, wenn die Dateien bereits vorbereitet sind.</p>\n<p>Die allgemeine 200-KB-Anleitung finden Sie unter <a href=\"/de/blog/bild-auf-200-kb-komprimieren-anleitung/\">Bild auf 200 KB komprimieren: Die komplette Anleitung</a>. Die praktischen Schritte stehen unter <a href=\"/de/blog/bild-auf-200-kb-komprimieren-so-geht-es/\">Bild auf 200 KB komprimieren: So geht es</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Wie groß sollte mein Jobportal-Profilfoto sein?","answer":"Die meisten Jobportale akzeptieren ein Foto unter 200 KB, oft mit einer empfohlenen Größe um 600 mal 600 Pixel im JPG-Format. Prüfen Sie die Regeln des jeweiligen Portals, denn manche begrenzen auf 100 KB oder 50 KB. Verwenden Sie immer JPG, es sei denn, das Portal listet ausdrücklich ein anderes Format."},{"question":"Kann ich ein WebP-Foto in ein Jobportal hochladen?","answer":"Meist nicht. Die meisten Jobportale akzeptieren nur JPG und PNG, und eine WebP-Datei wird abgelehnt. Verwenden Sie JPG für Portal-Uploads, auch wenn WebP etwas besser aussehen kann – eine abgelehnte Datei ist nutzlos, egal wie gut sie aussieht."},{"question":"Mein Zeugnisscan ist nach dem Komprimieren auf 200 KB verschwommen. Was ist schiefgelaufen?","answer":"Die Scanauflösung war vielleicht zu niedrig oder die Quelle war bereits komprimiert. Scannen Sie mit 300 DPI erneut und komprimieren Sie frisch vom neuen Scan. Wenn der kleinste Text trotzdem verschwimmt, versuchen Sie die WebP-Ausgabe oder prüfen Sie, ob das Portal eine größere Dateigröße akzeptiert."},{"question":"Brauche ich ein professionelles Foto für ein Jobportal?","answer":"Ein professionelles Studiofoto hilft, aber ein sauberes, gut beleuchtetes Handyfoto vor schlichtem Hintergrund funktioniert problemlos. Gutes Licht, ein gerader Winkel und ein zentriertes Gesicht zählen mehr als eine teure Kamera. Vermeiden Sie Selfies aus Armlänge."},{"question":"Kann ich dasselbe komprimierte Foto für mehrere Portale verwenden?","answer":"Ja, wenn die Regeln übereinstimmen. Prüfen Sie zuerst jedes Portal, denn Grenzen und Abmessungen unterscheiden sich. Ein Foto, das für ein 200-KB-Portal gemacht wurde, kann auf einem 50-KB-Portal scheitern, und ein quadratisches Foto passt vielleicht nicht für ein Portal, das ein Rechteck will."},{"question":"Warum lehnt das Portal mein 199-KB-Foto trotzdem ab?","answer":"Das Problem liegt meist am Format oder an den Abmessungen und nicht an der Größe. Vergewissern Sie sich, dass das Portal JPG akzeptiert, prüfen Sie die geforderten Pixelabmessungen und lesen Sie die genaue Fehlermeldung. Manche Portale lehnen Fotos auch mit dem falschen Seitenverhältnis ab."}];
